import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { projectLogic } from 'scenes/projectLogic'

import { hogFlowsReputationRetrieve } from 'products/workflows/frontend/generated/api'
import type {
    AwsTenantReputationApi,
    EmailSendingRatesApi,
    IspSendingHealthApi,
    TeamEmailReputationResponseApi,
    WorkflowEmailSendingRatesApi,
} from 'products/workflows/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowsReputationLogicValues {
    currentProjectId: number | null // projectLogic
    awsReputation: AwsTenantReputationApi | null
    ispSendingHealth: readonly IspSendingHealthApi[]
    reputationResponse: TeamEmailReputationResponseApi | null
    reputationResponseLoading: boolean
    search: string
    teamReputation: EmailSendingRatesApi | null
    workflowSnapshots: readonly WorkflowEmailSendingRatesApi[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowsReputationLogicActions {
    loadReputation: () => {
        value: true
    }
    loadReputationFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadReputationSuccess: (
        reputationResponse: TeamEmailReputationResponseApi | null,
        payload?: {
            value: true
        }
    ) => {
        reputationResponse: TeamEmailReputationResponseApi | null
        payload?: {
            value: true
        }
    }
    setSearch: (search: string) => {
        search: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowsReputationLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        awsReputation: (reputationResponse: TeamEmailReputationResponseApi | null) => AwsTenantReputationApi | null
        teamReputation: (reputationResponse: TeamEmailReputationResponseApi | null) => EmailSendingRatesApi | null
        ispSendingHealth: (reputationResponse: TeamEmailReputationResponseApi | null) => readonly IspSendingHealthApi[]
        workflowSnapshots: (
            reputationResponse: TeamEmailReputationResponseApi | null
        ) => readonly WorkflowEmailSendingRatesApi[]
    }
}

export type workflowsReputationLogicType = MakeLogicType<
    workflowsReputationLogicValues,
    workflowsReputationLogicActions,
    Record<string, any>,
    workflowsReputationLogicMeta
>

export const workflowsReputationLogic = kea<workflowsReputationLogicType>([
    path(['products', 'workflows', 'frontend', 'Workflows', 'Reputation', 'workflowsReputationLogic']),
    connect(() => ({
        values: [projectLogic, ['currentProjectId']],
    })),
    actions({
        // Declared here (as well as auto-created by the loader) so kea-typegen sees a payload-less
        // action; without this, TS types the first loader arg as required and callers fail typecheck.
        loadReputation: true,
        setSearch: (search: string) => ({ search }),
    }),
    reducers({
        search: [
            '',
            {
                setSearch: (_, { search }) => search,
            },
        ],
    }),
    loaders(({ values }) => ({
        reputationResponse: [
            null as TeamEmailReputationResponseApi | null,
            {
                loadReputation: async (_, breakpoint) => {
                    if (!values.currentProjectId) {
                        return null
                    }
                    const search = values.search.trim()
                    const response = await hogFlowsReputationRetrieve(
                        String(values.currentProjectId),
                        search ? { search } : undefined
                    )
                    breakpoint() // a newer load superseded this one; discard the stale response
                    return response
                },
            },
        ],
    })),
    listeners(({ actions }) => ({
        // Search filters server-side (the response is capped to the worst 50 workflows), so each
        // keystroke needs a reload — debounced via the loader's own breakpoint on rapid typing.
        setSearch: async (_, breakpoint) => {
            await breakpoint(250)
            actions.loadReputation()
        },
    })),
    selectors({
        awsReputation: [
            (s) => [s.reputationResponse],
            (response: TeamEmailReputationResponseApi | null): AwsTenantReputationApi | null => response?.aws ?? null,
        ],
        teamReputation: [
            (s) => [s.reputationResponse],
            (response: TeamEmailReputationResponseApi | null): EmailSendingRatesApi | null =>
                response?.reputation ?? null,
        ],
        ispSendingHealth: [
            (s) => [s.reputationResponse],
            (response: TeamEmailReputationResponseApi | null): readonly IspSendingHealthApi[] => response?.isps ?? [],
        ],
        workflowSnapshots: [
            (s) => [s.reputationResponse],
            (response: TeamEmailReputationResponseApi | null): readonly WorkflowEmailSendingRatesApi[] =>
                response?.workflows ?? [],
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadReputation()
    }),
])
